CREATE TABLE "customers" (
  "CustomerID" INTEGER  -- e.g. 3, 5, 6,
  "Segment" TEXT  -- e.g. SME, LAM, KAM,
  "Currency" TEXT  -- e.g. EUR, CZK
);

CREATE TABLE "yearmonth" (
  "CustomerID" INTEGER  -- e.g. 39, 63, 172,
  "Date" TEXT  -- e.g. 201112, 201201, 201202,
  "Consumption" REAL  -- e.g. 528.3, 1598.28, 1931.36
)
